sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   if(newValue.length < 14){
		g_form.showFieldMsg('abha_number', 'Fill Correct ABHA Number', 'error');
		return;
   }

   var ga = new GlideAjax('CheckUniquenessUtils');
    ga.addParam('sysparm_name', 'isNumberUnique');
    ga.addParam('sysparm_number_val', newValue);
    ga.addParam('sysparm_current_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(response) {
        if (response === 'false') {
            g_form.showFieldMsg('abha_number', 'This value already exists. Please enter a unique number.', 'error');
            // g_form.setValue('your_number_field', '');
        } else {
            g_form.hideFieldMsg('abha_number');
        }
    });

}
